def choose_move(observation):
    # Defensive access with defaults; choose a simple, robust policy that works across tasks.
    # Prefer staying put if no information, otherwise move away from nearest threat or toward nearest goal.
    # Extract common fields defensively
    grid = observation.get("grid", [])
    me = observation.get("self", {})
    x = me.get("x", 0)
    y = me.get("y", 0)
    width = len(grid[0]) if grid else 0
    height = len(grid) if grid else 0

    # Helper to find nearest entity of a given type
    def nearest_of(entity_type):
        best = None
        best_dist = 9999
        if not grid:
            return None, None
        for oy, row in enumerate(grid):
            for ox, cell in enumerate(row):
                if isinstance(cell, dict) and cell.get("type") == entity_type:
                    dist = abs(ox - x) + abs(oy - y)
                    if dist < best_dist:
                        best_dist = dist
                        best = (ox, oy)
        return best, best_dist

    # Threats: "enemy" or "police" depending on game; fall back to "enemy"
    threat, threat_dist = nearest_of("enemy")
    if threat is None:
        threat, threat_dist = nearest_of("police")
    # Goal or resource for resource_collection: "resource" or "goal"
    resource, _ = nearest_of("resource")
    goal, _ = nearest_of("goal")

    dx = 0
    dy = 0

    # Strategy priority:
    # 1) Move away from nearest threat if close
    if threat is not None and threat_dist is not None:
        tx, ty = threat
        if threat_dist <= 2:
            if tx > x:
                dx = -1
            elif tx < x:
                dx = 1
            else:
                dx = 0
            if ty > y:
                dy = -1
            elif ty < y:
                dy = 1
            else:
                dy = 0
            # If both axes determined, normalize to a valid single-step
            if dx != 0 and dy != 0:
                # prefer move that increases distance more by prioritizing one axis
                if threat_dist >= 3:
                    dy = 0
                else:
                    dx = 0
            return [dx, dy]

    # 2) If resource nearby, move toward it
    if resource is not None:
        rx, ry = resource
        if rx > x:
            dx = 1
        elif rx < x:
            dx = -1
        else:
            dx = 0
        if ry > y:
            dy = 1
        elif ry < y:
            dy = -1
        else:
            dy = 0
        if dx != 0 or dy != 0:
            return [dx, dy]

    # 3) If goal known, move toward it
    if goal is not None:
        gx, gy = goal
        if gx > x:
            dx = 1
        elif gx < x:
            dx = -1
        else:
            dx = 0
        if gy > y:
            dy = 1
        elif gy < y:
            dy = -1
        else:
            dy = 0
        if dx != 0 or dy != 0:
            return [dx, dy]

    # 4) Otherwise, small random-like deterministic wander: prefer staying, then move toward center
    # Without randomness, push toward center to stay robust
    cx = width // 2 if width else 0
    cy = height // 2 if height else 0
    if x < cx:
        dx = 1
    elif x > cx:
        dx = -1
    else:
        dx = 0
    if y < cy:
        dy = 1
    elif y > cy:
        dy = -1
    else:
        dy = 0
    return [dx, dy]

